USE BWSdb
GO


-- 2024-02-12
-- Mike Lyman Axel serials

DECLARE @t TABLE (
	[ID] INT IDENTITY(0, 1),
	[Serial Number] NVARCHAR(MAX),
	[WO] NVARCHAR(MAX),
	[Quote] NVARCHAR(MAX),
	[Quote Date] DATETIME,
	[Model No] NVARCHAR(MAX),
	[Width] INT,
	[Spread] INT,
	[Customer] NVARCHAR(MAX),
	[CustContact] NVARCHAR(MAX),
	[CustCity] NVARCHAR(MAX),
	[CustProvice/State] NVARCHAR(MAX),
	[CustPhone] NVARCHAR(MAX),
	[DealerContact] NVARCHAR(MAX),
	[Selling Price] FLOAT,
	[DealerCompany] NVARCHAR(MAX),
	[DealerPhone] NVARCHAR(MAX),
	[Invoice Date] DATETIME,
	[Date In Service] DATETIME,
	[Date Registered] DATETIME,
	[Days To Sale] INT,
	[Country] NVARCHAR(MAX),
	[Initials] NVARCHAR(MAX)
);


UPDATE
	@t
SET
	[WO] = CAST([O].[WO#] AS NVARCHAR(MAX))
	,[Quote] = CAST([O].[Quote#] AS NVARCHAR(MAX))
	,[Quote Date] = [O].[Quote Date]
	,[Model No] = [O].[Model No]
	,[Width] = [O].[Width]
	,[Spread] = [O].[Spread]
	,[Customer] = [C].[Customer]
	,[CustContact] = [C].[Contact]
	,[CustCity] = [C].[City]
	,[CustProvice/State] = [C].[Province/State]
	,[CustPhone] = [C].[Phone]
	,[DealerContact] = [DSP].[Sales Person]
	,[DealerPhone] = [DSP].[Phone]
	,[Selling Price] = [O].[Price]
	,[DealerCompany] = [D].[COMPANY NAME]
	,[Invoice Date] = [O].[Invoice Date]
	,[Date In Service] = [O].[Date In Service]
	,[Date Registered] = [O].[Date Registered]
	,[Days To Sale] = DATEDIFF(DAY, [O].[Quote Date], [O].[Order Date])
	,[Country] = (CASE WHEN ISNULL([O].[US Sale], 0) = 1 THEN 'US' ELSE 'CDN' END)
	,[Initials] = [D].[Initials]
FROM
	@t [T]
LEFT JOIN
	[Orders] [O] WITH (NOLOCK)
ON
	[T].[Serial Number] = [O].[Serial Number]
LEFT JOIN
	[Dealers] [D] WITH (NOLOCK)
ON
	[O].[DealerID] = [D].[ID]
LEFT JOIN
	[BWSdb].[dbo].[Dealers_SalesPeople] [DSP] WITH (NOLOCK)
ON
	[O].[DealerSalesPersonID] = [DSP].[Dealers_SPID]
	AND [O].[DealerID] = [DSP].[DealerID]
LEFT JOIN
	[Customers] [C] WITH (NOLOCK)
ON
	[O].[Quote#] = [C].[Quote#]
WHERE
	[O].[WO#] IS NOT NULL
;

SELECT
	[WO]
	,[Serial Number]
	,[Quote]
	,[Quote Date]
	,[Model No]
	,[Width]
	,[Spread]
	,[Customer]
	,[CustContact]
	,[CustCity]
	,[CustProvice/State]
	,[CustPhone]
	,[DealerContact]
	,[DealerPhone]
	,[DealerCompany]
	,[Selling Price]
	,[Invoice Date]
	,[Date In Service]
	,[Date Registered]
	,[Days To Sale]
	,[Country]
	,[Initials]
	,[AXLE #1]
	,[AXLE #2]
	,[AXLE #3]
	,[AXLE #4]
	,[AXLE #5]
	,[Hoist]
	,[Suspension #1]
	,[Suspension #2]
	,[Suspension #3]
	,[Suspension #4]
	,[Suspension #5]
FROM
	[Axle] [A]
INNER JOIN
	@t [T]
ON
	[A].[WO#] = [T].[WO]
ORDER BY
	[Quote Date]
	--(CASE WHEN [T].[WO] = 10011358 THEN 0 ELSE 1 END)